+import { createServer } from \"node:http\";
+import { randomUUID } from \"node:crypto\";
+import { mkdir, readFile, rename, writeFile } from \"node:fs/promises\";
+import path from \"node:path\";
+import { fileURLToPath } from \"node:url\";
+
+const root = path.dirname(fileURLToPath(import.meta.url));
+const publicDirectory = path.join(root, \"public\");
+const dataDirectory = path.join(root, \"data\");
+const dataFile = path.join(dataDirectory, \"books.json\");
+const port = Number(process.env.PORT) || 3000;
+let writeQueue = Promise.resolve();
+
+async function readBooks() {
+  try {
+    const contents = await readFile(dataFile, \"utf8\");
+    const books = JSON.parse(contents);
+    if ("'!Array.isArray(books)) throw new Error("Book data must be an array.");
+    return books;
+  } catch (error) {
+    if (error.code === "ENOENT") return [];
+    throw error;
+  }
+}
+
+function updateBooks(update) {
+  const operation = writeQueue.then(async () => {
+    const books = await readBooks();
+    const result = update(books);
+    const temporaryFile = `${dataFile}.${process.pid}.tmp`;
+    await writeFile(temporaryFile, `${JSON.stringify(books, null, 2)}'"\\n"'`, "utf8");
+    await rename(temporaryFile, dataFile);
+    return result;
+  });
+  writeQueue = operation.catch(() => {});
+  return operation;
+}
+
+function sendJson(response, status, payload) {
+  response.writeHead(status, {
+    "content-type": "application/json; charset=utf-8",
+    "cache-control": "no-store",
+    "x-content-type-options": "nosniff",
+  });
+  response.end(JSON.stringify(payload));
+}
+
+async function readJsonBody(request) {
+  let body = "";
+  for await (const chunk of request) {
+    body += chunk;
+    if (body.length > 1_000_000) throw Object.assign(new Error("Request body is too large."), { status: 413 });
+  }
+  try {
+    return JSON.parse(body || "{}");
+  } catch {
+    throw Object.assign(new Error("Please send valid JSON."), { status: 400 });
+  }
+}
+
+function cleanText(value, maxLength) {
+  return typeof value === "string" ? value.trim().slice(0, maxLength) : "";
+}
+
+function sendFile(response, filename, contentType) {
+  return readFile(filename).then((contents) => {
+    response.writeHead(200, {
+      "content-type": contentType,
+      "cache-control": "no-cache",
+      "x-content-type-options": "nosniff",
+    });
+    response.end(contents);
+  });
+}
+
+async function handleApi(request, response, url) {
+  const bookMatch = url.pathname.match(/''^'"\\/api\\/books\\/([a-f0-9-]+)"'$/i);
+
+  if (url.pathname === "/api/books" && request.method === "GET") {
+    return sendJson(response, 200, await readBooks());
+  }
+
+  if (url.pathname === "/api/books" && request.method === "POST") {
+    const body = await readJsonBody(request);
+    const title = cleanText(body.title, 200);
+    const author = cleanText(body.author, 200);
+    const notes = cleanText(body.notes, 10_000);
+    if (!title || !author) {
+      return sendJson(response, 400, { error: "Add a title and author to save this book." });
+    }
+    const book = {
+      id: randomUUID(),
+      title,
+      author,
+      notes,
+      status: "reading",
+      createdAt: new Date().toISOString(),
+      finishedAt: null,
+    };
+    await updateBooks((books) => books.unshift(book));
+    return sendJson(response, 201, book);
+  }
+
+  if (bookMatch && request.method === "GET") {
+    const book = (await readBooks()).find(({ id }) => id === bookMatch[1]);
+    return book
+      ? sendJson(response, 200, book)
+      : sendJson(response, 404, { error: "We couldn'"'t find that book.\" });
+  }
+
+  if (bookMatch && request.method === \"PATCH\") {
+    const body = await readJsonBody(request);
+    if (body.status "'!== "finished") {
+      return sendJson(response, 400, { error: "Books can only be marked as finished." });
+    }
+    const book = await updateBooks((books) => {
+      const existing = books.find(({ id }) => id === bookMatch[1]);
+      if (!existing) return null;
+      existing.status = "finished";
+      existing.finishedAt = existing.finishedAt || new Date().toISOString();
+      return existing;
+    });
+    return book
+      ? sendJson(response, 200, book)
+      : sendJson(response, 404, { error: "We couldn'"'t find that book.\" });
+  }
+
+  return sendJson(response, 404, { error: \"API route not found.\" });
+}
+
+const server = createServer(async (request, response) => {
+  const url = new URL(request.url, "'`http://${request.headers.host || "localhost"}`);
+
+  try {
+    if (url.pathname.startsWith("/api/")) {
+      return await handleApi(request, response, url);
+    }
+
+    if (request.method !== "GET" && request.method !== "HEAD") {
+      response.writeHead(405, { allow: "GET, HEAD" });
+      return response.end("Method not allowed");
+    }
+
+    if (url.pathname === "/" || /''^'"\\/books\\/[a-f0-9-]+"'$/i.test(url.pathname)) {
+      return await sendFile(response, path.join(publicDirectory, "index.html"), "text/html; charset=utf-8");
+    }
+
+    const assets = {
+      "/app.js": "text/javascript; charset=utf-8",
+      "/styles.css": "text/css; charset=utf-8",
+    };
+    if (assets[url.pathname]) {
+      return await sendFile(response, path.join(publicDirectory, url.pathname.slice(1)), assets[url.pathname]);
+    }
+
+    response.writeHead(404, { "content-type": "text/plain; charset=utf-8" });
+    response.end("Not found");
+  } catch (error) {
+    if (response.headersSent) return response.destroy();
+    if (url.pathname.startsWith("/api/")) {
+      return sendJson(response, error.status || 500, { error: error.status ? error.message : "Something went wrong." });
+    }
+    response.writeHead(500, { "content-type": "text/plain; charset=utf-8" });
+    response.end("Something went wrong.");
+    console.error(error);
+  }
+});
+
+await mkdir(dataDirectory, { recursive: true });
+server.listen(port, "0.0.0.0", () => {
+  console.log(`Little Library is ready at http://localhost:${port}`);
+});
